def comps(g, color):
 seen=set(); out=[]
 for r in range(len(g)):
  for c in range(len(g[0])):
   if g[r][c]==color and (r,c) not in seen:
    st=[(r,c)]; seen.add((r,c)); cells=[]
    while st:
     p=st.pop(); cells.append(p)
     for q in ((p[0]-1,p[1]),(p[0]+1,p[1]),(p[0],p[1]-1),(p[0],p[1]+1)):
      rr,cc=q
      if 0<=rr<len(g) and 0<=cc<len(g[0]) and g[rr][cc]==color and q not in seen: seen.add(q);st.append(q)
    out.append(cells)
 return out
